#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long add(long long x, long long y) {
    return ((x + y) % MOD + MOD) % MOD;
}

long long mult(long long x, long long y) {
    return ((x * y) % MOD + MOD) % MOD;
}

long long exp(long long base, long long power) {
    long long result = 1;
    long long cur = base;
    long long p = power;
    while (p > 0) {
        if (p & 1) result = mult(result, cur);
        cur = mult(cur, cur);
        p >>= 1;
    }
    return result;
}

long long inv(long long x) {
    return exp(x, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    int k;
    cin >> n >> m >> k;
    vector<vector<long long>> dp(k + 1, vector<long long>(k + 1, 0));
    dp[0][0] = 1;
    for (int i = 0; i < k; i++) {
        for (int j = 0; j < k; j++) {
            dp[i + 1][j] = add(dp[i + 1][j], mult(dp[i][j], j));
            dp[i + 1][j + 1] = add(dp[i + 1][j + 1], mult(dp[i][j], n - j));
        }
    }
    long long total = 0;
    for (int i = 1; i <= k; i++) {
        total = add(total, mult(dp[k][i], exp(inv(m), i)));
    }
    cout << total << "\n";
    return 0;
}
